TAX_RATE = 0.08


def total(items: list[dict[str, float]]) -> float:
    return sum(i['price'] * i['qty'] for i in items)


def tax(items: list[dict[str, float]]) -> float:
    return total(items) * TAX_RATE


def grand(items: list[dict[str, float]]) -> float:
    """Return the total plus tax for all items."""
    return total(items) + tax(items)
